const body = $input.first().json.body || $input.first().json;
let machineId = (body.machine_id || '').trim();
machineId = machineId.replace(/[^A-Za-z0-9_-]/g, '');
return { json: { machine_id: machineId } };

const rows = $input.first().json || [];
const arr = Array.isArray(rows) ? rows : [rows];
const count = arr.length;
let text = '';
if (count === 0) {
  text = '未找到维修记录';
} else {
  text = arr.map((r, i) => `${i+1}. ${r.pm_date || ''} ${r.pm_type || ''} 维修人: ${r.technician || ''} ${r.description || ''}`).join('\n');
}
return { json: { records: arr, count: count, summary: text } };
